<script setup lang="ts">
/**
 * A round mark identifying a person or workspace (`design/components/avatar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, ref } from 'vue'

import { Icon, avatarTone, initialsOf } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/avatar.module.css'

export type AvatarSize = NonNullable<AvatarProps['size']>

export interface AvatarProps {
  /**
   * Set only when the avatar stands alone; beside a visible name it would repeat the name, so it
   * is `aria-hidden` instead.
   */
  label?: string
  /**
   * Initials come from this. "Ada Lovelace" → AL; one word → its first two.
   */
  name: string
  size?: 'sm' | 'md' | 'lg'
  src?: string
}

defineOptions({ name: 'Avatar', inheritAttrs: false })

const props = withDefaults(defineProps<AvatarProps>(), { size: 'md' })
const failed = ref('')
const initials = computed(() => initialsOf(props.name))
const showImage = computed(() => props.src !== undefined && failed.value !== props.src)
const fallback = computed(() => (initials.value === '' ? 'icon' : 'initials'))
const named = computed(() => props.label !== undefined)
</script>

<template>
  <span
    :class="styles.avatar"
    :data-size="size"
    :data-fallback="showImage ? undefined : fallback"
    :data-tone="fallback === 'initials' && !showImage ? avatarTone(name) : undefined"
    :role="named ? 'img' : undefined"
    :aria-label="label"
    :aria-hidden="!named ? true : undefined"
    data-member="avatar"
  >
    <!-- image -->
    <img
      v-if="showImage"
      :class="styles.image"
      :src="src"
      alt=""
      draggable="false"
      @error="failed = src ?? ''"
    />
    <Icon v-if="fallback === 'icon'" name="user" :size="size" />
    <!-- initials -->
    <span v-else :class="styles.initials">
      {{ initials }}
    </span>
  </span>
</template>
